const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if(!reduced.matches&&'IntersectionObserver' in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.04});document.querySelectorAll('.document-section').forEach((s,i)=>{if(i)s.classList.add('reveal');io.observe(s)})}
let queued=false;function update(){const max=document.documentElement.scrollHeight-innerHeight;document.documentElement.style.setProperty('--progress',max?Math.min(1,scrollY/max):0);if(!reduced.matches){document.querySelectorAll('.hero-person').forEach((e,i)=>e.style.setProperty('--shift',`${scrollY*(i?-.025:-.04)}px`))}queued=false}addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});update();
